"""Block-structure boundary; inline syntax is intentionally not handled here."""

from dataclasses import dataclass, field

from references import ReferenceCollector


@dataclass(frozen=True)
class Block:
    kind: str
    content: str = ""
    level: int | None = None
    children: tuple["Block", ...] = ()


@dataclass(frozen=True)
class Document:
    blocks: tuple[Block, ...]
    references: ReferenceCollector = field(compare=False)


def parse_blocks(text: str) -> Document:
    """Build the initial block tree; inline parsing happens after this phase."""
    lines = text.splitlines()
    blocks: list[Block] = []
    references = ReferenceCollector()
    paragraph: list[str] = []

    def flush_paragraph() -> None:
        if paragraph:
            blocks.append(Block("paragraph", "\n".join(paragraph)))
            paragraph.clear()

    for line in lines:
        if not line.strip():
            flush_paragraph()
            continue
        if line.startswith("#"):
            marker = line.split(" ", 1)
            if len(marker) == 2 and 1 <= len(marker[0]) <= 6:
                flush_paragraph()
                blocks.append(Block("heading", marker[1].rstrip("#").rstrip(), len(marker[0])))
                continue
        paragraph.append(line)
    flush_paragraph()
    return Document(tuple(blocks), references)
